    {
        g.lastSearch = needle;
        g.lastSearchSmartCase = smartCase;
    }
    void searchBalanced(bool forward, QChar needle, QChar other);
    int searchBalancedPosition(int from, bool forward, QChar needle, QChar other,
                              int levels) const;
