    void moveUp(int n = 1) { moveDown(-n); }
    void moveDown(int n = 1);
    bool moveUpVisually(int n = 1) { return moveDownVisually(-n); }
    bool moveDownVisually(int n = 1);
    bool moveCursorByScreenLine(QTextCursor *tc, QTextCursor::MoveOperation op,
                                QTextCursor::MoveMode mode = QTextCursor::MoveAnchor) const;
    // A "-" among cpoptions makes a count that reaches past the first or the
    // last line an error, where the motion otherwise stops there (measured).
    bool countFitsInDocument(int n) const {
        if (!s.cpoOptions().contains('-'))
            return true;
        const int line = blockAt(position()).blockNumber() + n;
        return line >= 0 && line < document()->blockCount();
    }
    bool moveVertically(int n = 1) {
        if (g.gflag) {
            if (!moveDownVisually(n))
                return false;
            g.movetype = MoveExclusive;
            return true;
        }
        const int blockNumber = blockAt(position()).blockNumber();
        if (n > 0 ? blockNumber + 1 >= document()->blockCount() : blockNumber == 0)
            return false;
        if (!countFitsInDocument(n))
            return false;
        g.movetype = MoveLineWise;
        moveDown(n);
        return true;
    }
    void movePageDown(int count = 1);
    void movePageUp(int count = 1) { movePageDown(-count); }
    void dump(const char *msg) const {
        qDebug() << msg << "POS: " << anchor() << position()
            << "VISUAL: " << g.visualMode;
    }
    void moveRight(int n = 1) {
        if (isVisualCharMode()) {
            const QTextBlock currentBlock = block();
            const int max = currentBlock.position() + currentBlock.length() - 1;
            const int pos = position() + n;
            setPosition(qMin(pos, max));
        } else {
            m_cursor.movePosition(Right, KeepAnchor, n);
        }
        if (atEndOfLine())
            q->fold(1, false);
        setTargetColumn();
    }
    void moveLeft(int n = 1) {
        m_cursor.movePosition(Left, KeepAnchor, n);
        setTargetColumn();
    }
    // Not moveRight(), whose visual-mode clamp is the "l" motion stopping at
    // the last character of the line. A text object steps over the line end.
    void moveToNextCharacter() {
        m_cursor.movePosition(Right, KeepAnchor);
        if (atEndOfLine()) {
            q->fold(1, false);
            m_cursor.movePosition(Right, KeepAnchor);
        }
        setTargetColumn();
    }
    void moveToPreviousCharacter() {
        moveLeft();
        if (atBlockStart())
            moveLeft();
    }
    void setAnchor() {
        m_cursor.setPosition(position(), MoveAnchor);
    }
    void setAnchor(int position) {
        m_cursor.setPosition(position, KeepAnchor);
    }
    void setPosition(int position) {
        m_cursor.setPosition(position, KeepAnchor);
    }
    void setAnchorAndPosition(int anchor, int position) {
        m_cursor.setPosition(anchor, MoveAnchor);
        m_cursor.setPosition(position, KeepAnchor);
    }

