public:
    QTextEdit *m_textedit;
    QPlainTextEdit *m_plaintextedit;
    Utils::PlainTextEdit *m_qcPlainTextEdit;
    bool hasValidEditor();

    bool m_inFakeVim; // true if currently processing a key press or a command

    FakeVimHandler *q;
    int m_register;
    BlockInsertMode m_visualBlockInsert;
    // The column a block insert types in where the lines it covers do not
    // reach it, which is no column of theirs, and the column it leaves the
    // cursor in, which is where the first of those lines ends. -1 where the
    // lines do reach the block.
    int m_visualBlockColumn = -1;
    int m_visualBlockEndColumn = 0;

    // Characters overwritten during the current Replace mode session, so that
    // <BS> can restore them (QTCREATORBUG-12120). A newline sentinel marks a
    // character that was appended past the end of the line (nothing to
    // restore, just remove it again).
    QString m_replacedChars;
    // What replace mode has written over, and how often the count asks for it.
    QString m_replaceTyped;
    int m_replaceCount = 0;
    // What the last insertText() put in, which is what a put leaves the two
    // marks on.
    int m_lastInsertedFrom = -1;
    int m_lastInsertedTo = -1;
    // Behind the text the last put inserted, which is where "gp" ends up.
    int m_lastPutEnd = -1;

    // Block number of a freshly auto-indented line that has not received any
    // typed content yet. Leaving such a line untouched removes the automatic
    // indentation again, matching Vim (QTCREATORBUG-15009). -1 means none.
    int m_autoIndentBlock = -1;
    // Set while ":insert", ":append" or ":change" is reading lines, which a line
    // holding just a dot ends.
    bool m_exAppendMode = false;
    // Width of the automatic indentation the last auto-indented line received.
    int m_autoIndentSize = 0;
    // The comment leader put in automatically, and the line it went to.
    int m_commentLeaderBlock = -1;
    QString m_commentLeaderText;

    // The key typed before the current one in insert mode, which "0 CTRL-D"
    // and "^ CTRL-D" look at to tell themselves from a plain CTRL-D.
    Input m_lastInsertInput;
    // Whether "<C-g>U" held the edit block over the movement just made, which
    // keeps the cursor leaving the inserted text from ending it either.
    bool m_movedJoined = false;
    // The indentation the next line is to get where it is not the indenter's
    // to decide, as with "^ CTRL-D". -1 means none.
    int m_oldIndent = -1;

    bool m_anchorPastEnd;
    bool m_positionPastEnd; // '$' & 'l' in visual mode can move past eol
    // How far behind the end of its line the anchor of a selection stands,
    // where 'virtualedit' lets it stand there at all.
    int m_anchorCells = 0;
    // Set where a yank of the columns of a tab has chosen the wanted column
    // itself, so that the movement it belongs to does not ask for it again.
    bool m_keepTargetColumn = false;

    // Where the blanks a tab split for a visual block became begin on the
    // first of the lines it covers, for the commands that leave the cursor
    // where the block began rather than where they wrote.
    int m_blockSplitColumn = -1;
    // Where an insert that "<C-o>" interrupts stood past the end of its line,
    // so that it goes back there.
    bool m_insertPastEnd = false;
    int m_insertPastEndLine = -1;
    bool m_motionFailed = false; // the last motion had nowhere to go
    // Vim's called_vim_beep: a command that could not be carried out said so,
    // which is the only thing assert_beeps() looks at. Nothing here sounds a
    // bell, and an error message is not a beep either (measured).
    bool m_beeped = false;
    int m_lastRemovalPosition = -1; // where text was taken away, to see a replace
    int m_indentLine = 0; // the line an 'indentexpr' is being asked about, for v:lnum
    int m_formatLines = 0; // the lines a 'formatexpr' is being asked about, for v:count
    bool formatWithExpression(const Range &range);
    bool formatWithProgram(const Range &range);
    void filterThroughProgram(const QString &program, int beginBlock, int endBlock);

    // The tag a jump was asked for, kept until the editor answers whether it
    // found the symbol. Empty where the answer is not wanted.
    QString m_pendingTagJump;

    QString m_currentFileName;
    // ":file {name}" has named the buffer since it was last written, which is
    // what "[Not edited]" reports until a write to that name clears it again.
    bool m_notEdited = false;
    // The name as it stands, which is what bufname() answers with. Vim only
    // shortens it against the working directory when that directory changes,
    // so a name that was absolute when the buffer opened stays absolute.
    QString m_bufferName;

    // Buffer-ish Vimscript variables (b:/w:/t:, kept with their prefix). The
    // session-wide ones live in g.variables, see variableStore().
    QHash<QString, VimValue> m_variables;
    // User functions and the local (a:/l:) scope stack, one frame per active
    // call.
    struct UserFunction {
        QStringList params;
        QStringList defaults; // parallel to params; "" if no default value
        QString varargName; // Vim9 "...name": binds the extra arguments as a list
        QList<ExCommand> body;
        bool vim9 = false; // a :def function (bare-name args, Vim9 semantics)
        // ":function F() range" is handed the whole range at once; without it
        // Vim calls the function once for each line of the range.
        bool takesRange = false;
        // The script it was defined in, which is what "<SID>" stands for there.
        int scriptId = 0;
    };
    // What a ":defer" queued: both the callable and its arguments are settled
    // when the ":defer" runs, not when the call happens.
    struct DeferredCall {
        VimValue callable;
        QList<VimValue> args;
    };
    // One entry of a quickfix or location list, as setqflist() takes it.
    struct QuickfixEntry
    {
        int bufnr = 0;
        int lnum = 0;
        int endLnum = 0;
        int col = 0;
        int endCol = 0;
        int nr = 0;
        bool vcol = false;
        bool valid = false;
        QString pattern;
        QString text;
        QString type;
        QString module;
    };

    struct QuickfixList
    {
        QList<QuickfixEntry> items;
        QString title;
        VimValue context = VimValue(QString());
        int id = 0;
        int changedTick = 0;
        // The entry the list stands on, one based, zero while it has none.
        int index = 0;
    };

    // Vim keeps a stack of at most ten lists, one for the quickfix list and one
    // for every window's location list.
    struct QuickfixStack
    {
        QList<QuickfixList> lists; // oldest first
        int current = -1;          // where the stack stands, -1 while it is empty
    };

    // A buffer this session knows of besides the one a handler works on, which
    // is what bufadd() makes: unlisted and unloaded until bufload() reads the
    // file. Nothing shows it, so it has neither a cursor nor a window.
    struct KnownBuffer
    {
        int number = 0;
        QString name; // as it was given, Vim does not expand it either
        QStringList lines; // what bufload() read
        QMap<QString, VimValue> variables; // its own b: scope
        int changedTick = 1;
        // The line ":bdelete" leaves remembered for it: nothing shows the
        // buffer, so there is no cursor to take one from, and an unload
        // leaves none (measured).
        int lnum = 0;
        bool loaded = false;
        bool modified = false;
    };

    struct AutoCommand {
        QString group; // the ":augroup" it belongs to, empty for none
        QString event;
        QString pattern;
        QString command;
        int scriptId = 0; // whose "s:" the command reaches, as in Vim
        bool once = false; // "++once": taken off the list as it is picked up
        bool nested = false; // "++nested": events the command sets off run too
    };
    struct UserCommand {
        QString replacement;
        int scriptId = 0;
        // What "-nargs=" allowed, as Vim writes it: '0' where nothing was said.
        QChar nargs = '0';
        // What the other attributes said. Only the listing reads some of them.
        bool bang = false;
        // Whether an address may be given, and whether it counts rather than
        // addresses, with the default each carries.
        bool takesRange = false;
        bool takesCount = false;
        QString rangeDefault;
        QString countDefault;
        bool reg = false;
        bool buffer = false;
        bool bar = false;
        QString range;    // the "Address" column: "", ".", "%", "5", "0c"
        QString addrType; // its second word: "", "?", "buf", "win", ...
        QString complete;
    };
    // What an autocommand may ask about while it runs, and nothing outside one:
    // "v:event", "v:char", and what "<afile>" stands for where the event is
    // about something other than a file. Put back after each firing, so a
    // nested event leaves the outer one reading its own.
    struct EventContext {
        QMap<QString, VimValue> data;
        QString typedChar;
        QString target;
        // What "<afile>" stands for where that is not what the pattern was
        // matched against: nothing at all for an event about no file, the new
        // directory for a DirChanged, the file in the buffer for an event
        // whose pattern matched something else.
        std::optional<QString> file;
        int buffer = 0; // what "<abuf>" stands for, zero for this handler's
        QString group; // where set, only this group's autocommands are fired
        // The "v:" variables this firing brings with it, e.g. v:option_new for
        // an OptionSet. They hold only while the autocommand runs.
        QMap<QString, VimValue> vars;
    };
    bool m_noAutocmd = false; // ":noautocmd" is suppressing autocommands
    int m_autocmdDepth = 0; // nesting level of running autocommands
    // Whether the FileType event has fired for this buffer from a file type
    // that was not just a guess, which is what ":setf" checks so that the first
    // rule recognizing a buffer wins. Reset when the buffer is read again.
    bool m_didFileType = false;
    QString m_fileType; // matched by FileType autocommands
    QString m_syntax; // what "&syntax" reads back; Syntax autocommands
    // 'colorcolumn' as it was typed, which is what Vim keeps: a comma list
    // whose entries may be relative to 'textwidth'. Qt Creator draws ONE
    // margin, so the first absolute entry is what it is asked for.
    QString m_colorColumn;
    QString m_eventIgnore; // 'eventignore', as typed
    QString m_eventIgnoreWin; // 'eventignorewin', as typed
    bool setEventIgnore(const QString &value);
    bool setEventIgnoreWin(const QString &value);
    bool eventIgnored(const QString &event) const;
    int m_foldColumn = 0; // 'foldcolumn', a width where Creator has a switch
    // 'foldenable' and 'foldlevel'. Both act on the folds Qt Creator has
    // worked out; 'foldmethod' only says how that is done.
    bool m_foldEnable = true;
    int m_foldLevel = 0;
    QString m_foldMethod = "syntax";
    // ":set readonly" on a buffer whose file is perfectly writable. The
    // editor's own read-only state is the other half of what "&readonly"
    // answers, and no flag can talk it round.
    bool m_markedReadOnly = false;
    // 'modifiable'. Unlike 'readonly' this one refuses the change itself.
    bool m_modifiable = true;
    // Whether the "changing a readonly file" warning has been given for this
    // buffer yet. Vim gives it once, and a write or a reload arms it again.
    bool m_warnedReadOnly = false;
    // Buffer-local 'commentstring'; empty means derive it from the file type.
    QString m_commentString;
    // The pieces of the current match, while a "\=" replacement is being
    // worked out, for submatch() to reach.
    QStringList m_subMatches;
    // What bufnr() reports for this buffer, taken on first use.
    QuickfixStack m_locationList; // this window's, where the quickfix stack is shared
    int m_bufferNumber = 0;
    // Syntax item names seen so far; a name's position here is its synID().
    QStringList m_syntaxNames;
    bool m_vim9 = false; // Vim9-script semantics are active
    int m_defDepth = 0; // how many ":def" bodies are running
    QStringList m_scriptFileStack; // scripts currently sourcing, innermost last
    // Whose "s:" is in reach, innermost last: a function carries the script that
    // defined it, an autocommand or user command the one that registered it.
    QList<int> m_scriptContexts;
    int scriptIdFor(const QString &path) const;
    int currentScriptId() const;
    QString functionKey(const QString &name) const;
    // Which statement each frame is running, for <stack> and v:throwpoint.
    QList<int> m_scriptLines;
    QList<int> m_functionLines;
    // Where in the FILE each function frame stands, which is what
    // getstacktrace() reports - m_functionLines beside it counts the
    // statements of the body instead, which is what a throwpoint names.
    // Zero for a function that came from no file.
    QList<int> m_functionSourceLines;
    QString m_throwpoint; // where the exception being carried was thrown
    QStringList m_callStack; // user functions currently running, for <stack>
    QList<QList<DeferredCall>> m_deferredCalls; // one list per running function
    QString sourceChain(bool asThrowPoint, bool bareInnermost = false) const;
    QSet<QString> m_sourcesInFlight; // guards against :source/:import cycles
    QList<QHash<QString, VimValue>> m_localScopes;
    bool m_returning = false;
    VimValue m_returnValue;
    bool m_throwing = false; // an exception raised by :throw is in flight
    QString m_exception;
    // The range a ":call" was given, for "a:firstline" and "a:lastline".
    int m_callFirstLine = 0;
    int m_callLastLine = 0;
    int m_tryDepth = 0; // how many ":try" bodies are being run
    bool m_finishing = false; // :finish - stop running the current command list
    int m_messageSilence = 0; // >0 while inside :silent
    bool m_silenceErrors = false; // :silent! also suppresses errors
    // ":filter" cuts a listing down to the entries whose relevant field
