// strptime() is POSIX and MSVC's and MinGW's C library have none. Vim documents the
// function as "Not available on all systems", tells a script to ask
// exists("*strptime") before using it, and ships no stand-in of its own - so
// neither does this. Where the platform has nothing to parse with, the name is
// absent, which is the answer a script is written to expect.
#ifdef Q_OS_WIN
static const bool haveStrptime = false;
#else
static const bool haveStrptime = true;
#endif

static bool isBuiltinFunction(const QString &name)
{
    if (name == "strptime")
        return haveStrptime;
    return builtinFunctionNames().contains(name);
}

// The characters Vim will not show, and writes in hex instead.
static bool unprintable(ushort u)
{
    static const struct { ushort from, to; } ranges[] = {
        {0x0080, 0x009f}, {0x180b, 0x180e}, {0x200b, 0x200f}, {0x202a, 0x202e},
        {0x2060, 0x206f}, {0xfeff, 0xfeff}, {0xfff9, 0xfffb}, {0xfffe, 0xffff}
    };
    for (const auto &range : ranges) {
        if (u >= range.from && u <= range.to)
            return true;
    }
    return false;
}

// What a string looks like where it is shown, which is what strtrans() answers
// and what a ":substitute" with an "l" among its flags prints: a character below
// a blank stands as "^" and the letter it is CTRL of, and 0x7f as "^?".
static QString shownAsTyped(const QString &text, bool lineBreakIsNul)
{
    QString shown;
    for (const QChar c : text) {
        const ushort u = c.unicode();
        if (u == '\n')
            // Vim holds a NUL as a line break and shows it so, while a register
            // really does hold line breaks.
            shown += lineBreakIsNul ? "^@" : "^J";
        else if (u < 0x20)
            shown += QLatin1Char('^') + QChar(u + 0x40);
        else if (u == 0x7f)
            shown += "^?";
        else if (unprintable(u))
            shown += QString("<%1>").arg(u, 2, 16, QLatin1Char('0'));
        else
            shown += c;
    }
    return shown;
}

// This handler drives one editor, so there is exactly one window: number 1, in
// tab page 1, with the id Vim would have given the first window it opened.
const qlonglong theWindowId = 1000;

static int utf8Length(uint codepoint)
{
    return codepoint < 0x80 ? 1 : codepoint < 0x800 ? 2 : codepoint < 0x10000 ? 3 : 4;
}

// Where each codepoint of a string starts, counted both ways, and whether it is
// a combining mark. What Vim calls a "character" is a codepoint - a surrogate
// pair is one of them, not the two units QString stores it in - and several of
// the functions below additionally fold a combining mark into the character it
// belongs to.
struct Codepoint
{
    int utf16Index;
    int byteIndex;
    bool combining;
};

static QList<Codepoint> codepointsOf(const QString &text)
{
    QList<Codepoint> out;
    int byteIndex = 0;
    for (int i = 0; i < text.size(); ) {
        const bool pair = text.at(i).isHighSurrogate() && i + 1 < text.size()
                          && text.at(i + 1).isLowSurrogate();
        const uint codepoint = pair ? QChar::surrogateToUcs4(text.at(i), text.at(i + 1))
                                    : text.at(i).unicode();
        const QChar::Category category = QChar::category(codepoint);
        out.append({i, byteIndex, category == QChar::Mark_NonSpacing
                                  || category == QChar::Mark_SpacingCombining
                                  || category == QChar::Mark_Enclosing});
        byteIndex += utf8Length(codepoint);
        i += pair ? 2 : 1;
    }
    return out;
}

// The codepoints that start a character, with a combining mark folded into the
// one before it when asked. A mark with nothing in front of it to belong to
// starts a character of its own - measured, "U+0301 a" is two characters even
// when folding.
static QList<Codepoint> charactersOf(const QString &text, bool fold)
{
    QList<Codepoint> out;
    for (const Codepoint &codepoint : codepointsOf(text)) {
        if (!fold || !codepoint.combining || out.isEmpty())
            out.append(codepoint);
    }
    return out;
}

// Where each character sits when the UTF-16 code units are the count, plus one
// more entry for the end of the string, so the last one is the whole length.
// The index is not the one into the QString: a combining mark folded into the
// character in front of it adds no unit of its own.
static QList<Codepoint> utf16Counted(const QString &text, bool fold)
{
    QList<Codepoint> out;
    int units = 0;
    for (const Codepoint &character : charactersOf(text, fold)) {
        out.append({units, character.byteIndex, character.combining});
        const int i = character.utf16Index;
        const bool pair = text.at(i).isHighSurrogate() && i + 1 < text.size()
                          && text.at(i + 1).isLowSurrogate();
        units += pair ? 2 : 1;
    }
    out.append({units, int(text.toUtf8().size()), false});
    return out;
}

// Between the two counts inside a string. Vim measures a string in BYTES:
// strlen(), stridx(), match() and the places matchstrpos() answers with are
// byte offsets, where strchars() and strcharpart() count characters. Measured
// on "a\303\244b\303\244c": strlen says 7 and match("b") 3, against 5 and 2
// for the characters. This one counts from zero, as a string index does.
static int byteIndexOfString(const QString &text, int chars)
{
    return int(text.left(qMax(0, chars)).toUtf8().size());
}

// The character a byte offset falls in, counted from zero. A byte inside a
// character belongs to it, so the offset comes back as the boundary at or in
// front of it; "after" asks for the one at or behind it instead, which is what
// a place to start searching from needs (measured: stridx() given a start in
// the middle of a character finds the NEXT one, not that one).
static int charIndexOfString(const QString &text, int bytes, bool after)
{
    if (bytes <= 0)
        return 0;
    const QList<Codepoint> points = codepointsOf(text);
    for (int i = 0; i < points.size(); ++i) {
        if (points.at(i).byteIndex >= bytes) {
            return after || points.at(i).byteIndex == bytes
                ? points.at(i).utf16Index : points.at(i - 1).utf16Index;
        }
    }
    return int(text.size());
}

// The element type of a container is the one all its members agree on. An empty
// container has no member to ask, so its element type stays undecided - written
// here as the empty slot in "list<>" - and takes on whatever it is compared
// against, however deeply nested. Only a real disagreement gives up and says
// "any"; an undecided slot that survives to the end prints as "any" too.
static QString unifyTypes(const QString &a, const QString &b)
{
    if (a.isEmpty() || b.isEmpty())
        return a.isEmpty() ? b : a;
    if (a == b)
        return a;
    for (const QLatin1String kind : {QLatin1String("list<"), QLatin1String("dict<")}) {
        if (a.startsWith(kind) && b.startsWith(kind)) {
            const int extra = kind.size() + 1;
            return kind + unifyTypes(a.mid(kind.size(), a.size() - extra),
                                     b.mid(kind.size(), b.size() - extra)) + ">";
        }
    }
    return "any";
}

static QString typeOf(const VimValue &value)
{
    switch (value.type()) {
    case VimValue::Number: return "number";
    case VimValue::Float: return "float";
    case VimValue::String: return "string";
    case VimValue::Bool: return "bool";
    case VimValue::Special: return "special";
    case VimValue::Blob: return "blob";
    case VimValue::Tuple: {
        // Measured: unlike a list, a tuple names EVERY element type -
        // "tuple<number, number>" - and an empty one is "tuple<any>".
        QStringList parts;
        for (const VimValue &item : *value.listData())
            parts.append(typeOf(item));
        if (parts.isEmpty())
            return "tuple<any>";
        return "tuple<" + parts.join(", ") + ">";
    }
    case VimValue::Func:
        // Nothing here is declared, so there is no signature to report: a
        // lambda has an unknown return type, a named function an untyped one.
        // FIXME: Vim answers with the signature of a builtin, e.g.
        // "func([unknown]): number" for strlen(). That wants a return type
        // recorded per builtin, which is a table rather than a rule.
        if (value.funcData() && value.funcData()->isLambda)
            return "func(...): [unknown]";
        return "func(...): any";
    case VimValue::List: {
        QString element;
        for (const VimValue &item : *value.listData())
            element = unifyTypes(element, typeOf(item));
        return "list<" + element + ">";
    }
    case VimValue::Dict: {
        QString element;
        for (const VimValue &item : *value.dictData())
            element = unifyTypes(element, typeOf(item));
        return "dict<" + element + ">";
    }
    }
    return "any";
}

