        *error = args.size() > 0 && arg(0).toBool()
                ? //: Easter egg error message of Vim's err_teapot() function.
                  Tr::tr("E503: Coffee is currently not available")
                : //: Easter egg error message of Vim's err_teapot() function.
                  Tr::tr("E418: I'm a teapot");
