        if (!builtinPattern(arg(1).toString(), &re, error))
            return false;
        const QRegularExpressionMatch mm = re.match(arg(0).toString());
        QList<VimValue> items;
        if (mm.hasMatch()) {
            for (int k = 0; k <= 9; ++k)
                items.append(VimValue(mm.captured(k)));
        }
        *result = VimValue::list(items);
        return true;
