        const double x = a.toFloat();
        double y = 0;
        if (name == "sqrt")
            y = std::sqrt(x);
        else if (name == "exp")
            y = std::exp(x);
        else if (name == "log")
            y = std::log(x);
        else if (name == "log10")
            y = std::log10(x);
        else if (name == "sin")
            y = std::sin(x);
        else if (name == "cos")
            y = std::cos(x);
        else if (name == "tan")
            y = std::tan(x);
        else if (name == "asin")
            y = std::asin(x);
        else if (name == "acos")
            y = std::acos(x);
        else if (name == "atan")
            y = std::atan(x);
        else if (name == "sinh")
            y = std::sinh(x);
        else if (name == "cosh")
            y = std::cosh(x);
        else // tanh
            y = std::tanh(x);
