        const QList<VimValue> items = *arg(0).listData();
        const VimValue func = arg(1);
        int i = 0;
        VimValue acc;
        if (args.size() > 2) {
            acc = arg(2);
        } else {
            if (items.isEmpty()) {
                *error = Tr::tr("E998: Reduce of an empty List with no initial value");
                return false;
            }
            acc = items.at(0);
            i = 1;
        }
        for (; i < items.size(); ++i) {
            VimValue r;
            if (!invokeCallable(func, {acc, items.at(i)}, &r, error))
                return false;
            acc = r;
        }
        *result = acc;
        return true;
