        if (a.startsWith('&') || a.startsWith('+')) {
            // "&opt" asks whether Vim has the option at all, "+opt" whether it
            // can be used, which for an option only known by name it cannot.
            const QString opt = optionNameFromLet(a);
            OptionKind kind = OptionKind::Boolean;
            ex = s.item(Utils::keyFromString(opt)) != nullptr
                 || isCommentStringOption(opt) || isFileTypeOption(opt)
                 || isSyntaxOption(opt) || isModifiedOption(opt)
                 || isReadOnlyOption(opt) || isModifiableOption(opt)
                 || !displayOptionName(opt).isEmpty()
                 || !documentOptionName(opt).isEmpty()
                 || isColorColumnOption(opt) || isEventIgnoreOption(opt)
                 || isEventIgnoreWinOption(opt)
                 || isFoldColumnOption(opt)
                 || isFoldEnableOption(opt) || isFoldLevelOption(opt)
                 || isFoldMethodOption(opt);
            if (!ex && a.startsWith('&'))
                ex = unimplementedOption(opt, &kind);
        } else if (a.startsWith('$'))
            ex = qEnvironmentVariableIsSet(a.mid(1).toLatin1().constData());
        else if (a.startsWith('*') || a.startsWith('?')) {
            // "*name" asks whether a function is there to be called, whether
            // built in, defined by a script or held by a variable as a Funcref.
            QString func = a.mid(1);
            if (func.startsWith("g:"))
                func = func.mid(2);
            VimValue held;
            ex = g.userFunctions.contains(functionKey(func)) || isBuiltinFunction(func)
                 || (variableValue(func, &held) && held.isFunc());
        } else {
            VimValue tmp;
            ex = variableValue(a, &tmp);
        }
