        const QString flags = arg(1).toString();
        const QFileInfo info(what);
        bool gone = false;
        if (flags.contains('r'))
            gone = info.isDir() ? QDir(what).removeRecursively() : QFile::remove(what);
        else if (flags.contains('d'))
            gone = info.isDir() && QDir().rmdir(what);
