            // stand, so it counts, and an empty line has only that one.
            if (column < 1 || column > int(lineContents(line).size()) + 1) {
                *error = Tr::tr("E964: Invalid column number: %1").arg(column);
                return false;
            }
            *p = CursorPosition(line - 1, column - 1);
            return true;
